"""Справочник стратегической карты Frontier International."""
import re
from combat_guides import table


def building_table(project):
    source = (project / "work/raw/dat/mapitemlist.dat.txt").read_text(encoding="utf8")
    names = dict(line.split(" = ", 1) for line in
                 (project / "text/orig/system.txt").read_text(encoding="utf-8-sig").splitlines() if " = " in line)
    terrain = ["Любая", "Равнины", "Город", "Водопой", "Лес", "Горы"]
    benefits = {"gold.add":"золото", "food.add":"еда", "resource.add":"ресурсы",
                "energy.add":"тёмная энергия", "addhp":"лечение", "addexp":"опыт",
                "addfc":"прирост силы", "addLNDhp":"стена"}
    rows = []
    for record in re.split(r"(?m)^ \(const\) %\[", source)[1:]:
        def number(key):
            return int(re.search(r'"'+key+r'" => (\d+)', record)[1])
        name = re.search(r'"name" => "([^"]+)"', record)[1].replace("\\'", "'")
        # extra.xp3 renames bu_23; the building stats are identical in both editions.
        if name == "Hotel":
            name = "Brothel"
        effects = re.findall(r"gmp\.([\w.]+)=(\d+)", record)
        rows.append((names[name], terrain[number("state")], number("cost"), number("addHP"),
                     ", ".join(f"{benefits[key]} +{value}" for key,value in effects) or "—"))
    return table(("Постройка","Местность","Золото","ОЗ","Эффект"),rows)


def campaign_pages(page, register, illustration, project):
    mode = """<p>При первом запуске доступны сюжетная кампания и три сложности. Красный крест рядом с кнопкой означает, что для неё нужно завершённое прохождение. Последний выбор на этом экране — луна. Щелчок по стихии запускает игру.</p>
<h2>Сюжет и повторное прохождение</h2><p>«Сюжет и бои» соединяет походы на карте со сценами новеллы. После первой победы открывается режим «Только бои». Он пропускает сюжет основной кампании. Самая низкая сложность в этом режиме — «Сложная». При переключении с лёгкой или обычной игра сама поднимает сложность.</p>
<p>Для «Новой игры+» нужен перенос из завершённой кампании. В новую игру переходят союзники, их имена, снаряжение, предметы и руда в магазине. «Новая армия» сбрасывает уровни бойцов до первого. «Перенос уровней» сохраняет накопленный уровень.</p>
<h2>Особые условия</h2><p>Можно включить несколько условий сразу. «Запас ресурсов» выставляет каждый из четырёх стартовых запасов на 500 000. «Атеизм» отключает тактические навыки обеих армий. Оба условия доступны после первого прохождения. Для «Переноса героев» требуется ещё и перенос сохранения. Командиры сохраняют состояние на момент финала, хотя отдельные события кампании всё ещё могут его изменить.</p>
<h2>Что меняется со сложностью</h2><p>На лёгкой враг не начинает вторжения, а бой можно выиграть кнопкой мгновенной победы. Лёгкая и обычная используют один исходный список вражеских отрядов. Для сложной, очень сложной и «Нидхёгга» игра загружает отдельные списки. Например, в исходном составе дозора Варкауса на очень сложной стоят варвар, тяжёлый пехотинец и осадный боец. В списке «Нидхёгга» у дозора шесть бойцов, включая тяжёлого пехотинца, воительницу и жрицу. В сюжетной кампании на «Нидхёгге» враг также быстрее готовит вторжения. В режиме «Только бои» темп подготовки фиксирован.</p>"""
    mode += table(("Сложность","Базовый прирост каждого запаса","Базовое лечение своего бойца, ОЗ",
                   "Базовое лечение врага, ОЗ","Лечение врага в главе 1 до построек, ОЗ"),
                  [("Лёгкая",500,50,25,39),("Обычная",400,40,50,98),("Сложная",400,30,75,167),
                   ("Очень сложная",400,20,100,236),("Нидхёгг",400,20,150,335)])
    mode += """<p>В новой кампании без переноса армия получает по 4 000 единиц каждого запаса на лёгкой сложности, по 3 000 на обычной, 2 500 на сложной, 2 000 на очень сложной и 1 500 на «Нидхёгге». Прирост в таблице указан за ход до прибавок от построек. Например, на лёгкой пашня в лагере Оулу поднимает доход еды с 500 до 520, золота с 500 до 540.</p>
<p>К базовому лечению врага в конце хода игра прибавляет надбавку за главу и бонус его построек. На обычной сложности в первой главе получается 50 + (40 + 8 × 1) = 98 ОЗ на бойца до построек.</p><h2>С какой луны начнётся поход</h2><p>Восемь кнопок задают первую фазу. За огнём идут лёд, ветер, земля, молния, вода, свет и тьма. После тьмы цикл начинается заново. Луна влияет на найм и боевые параметры. Если первый отряд строится вокруг бойцов одной стихии, их луна даст преимущество уже на старте.</p>"""
    mode += illustration("campaign/moons","Внизу экрана старта восемь стихий. Любая из кнопок подтверждает настройки кампании.")
    mode += '<p><a href="mechanics.html#moon">День, ночь и противоположные стихии →</a></p>'
    first = """<p>Кампания начинается в лагере на равнинах Оулу. На лёгкой сложности в казне 4 000 золота, по 4 000 единиц еды, ресурсов и тёмной энергии. На обычной у каждого запаса 3 000, на сложной — 2 500. Лагерь уже приносит доход. Первый бой можно начать, как только готовы отряды.</p>"""
    first += illustration("campaign/orders","Игра показывает ближайшую цель в лесу Курикка. Для нападения служит портрет гарнизона под названием земли.")
    first += """<h2>Подготовка в лагере</h2><ol><li>В <a href="recruitment.html">«Найме»</a> видны доступные бойцы, цены и титулы. Здесь же куют медальоны.</li><li>В <a href="formation.html">«Отрядах»</a> боец получает место в переднем или заднем ряду. Во вкладке командиров находятся герои, в том числе Локи. В <a href="equipment.html">«Снаряж.»</a> можно купить предметы и выдать их выбранному бойцу.</li><li>В <a href="army-plan.html">«Плане»</a> видны ОЗ отряда, цена лечения и его приказ. После подготовки «Карта» возвращает к землям. Щелчок по портрету вражеского гарнизона открывает нападение.</li></ol><p>Если хочется открыть встречи с Феной, общение можно включить уже в лагере. Заходите в <a href="call-events.html">«Вызов»</a>, чтобы проверить, появилась ли встреча после хода.</p>
<h2>Что видно вокруг Оулу</h2><p>Дороги соединяют соседние земли. Флаг над названием показывает владельца, под названием стоит портрет гарнизона. На первом ходу у леса Курикка и Варкауса по 230 ОЗ гарнизона, у берега озера Лоймаа — 764. В Оулу число 0040 рядом с монетой показывает доход своей пашни. Прочерки у вражеской земли в этой колонке обычны — карта показывает доход своих владений.</p>"""
    first += illustration("campaign/oulu","Оулу на восточной окраине карты. Внизу слева мини-карта, справа четыре запаса и их прирост.")
    first += """<h2>Значки местности в Оулу</h2><p>Под панелью земли значки идут слева направо в таком порядке. Звери получают +8%, летающие +8%, рыцари +16%, ночные −16% днём и +16% ночью. Первые три числа ночью сохраняются. Значки относятся к типам бойцов обеих армий, когда бой идёт на этой земле. Поправки всех подходящих типов складываются. Например, у летающего зверя выходит +16% в любое время, а у ночного рыцаря днём получается 0%, ночью +32%.</p>
<p>Игра умножает текущие на этом этапе атаку, защиту, скорость и боевой дух на итоговый процент и прибавляет целую часть результата к каждому показателю. При атаке 50 прибавка +8% даст 54, а штраф −16% оставит 42. ОЗ и стена от этих значков не меняются. «Отмена влияния местности» убирает поправки для обеих сторон. «Перевозка войск» убирает отрицательные значения по отдельным типам у своего отряда и сохраняет положительные. Поэтому ночной рыцарь в отряде с этим навыком получит днём +16% вместо 0%.</p>"""
    first += """<p>В нижней панели «Общие ОЗ» относятся к гарнизону. У своего стартового лагеря на снимке 0/0. ОЗ самой постройки указаны отдельно в «Стройке». Четыре счётчика справа читаются сверху вниз: еда, ресурсы, тёмная энергия, золото. Число слева от стрелки — запас, справа — прирост.</p><h2>Когда двигаться дальше</h2><p>«Ход» передаёт инициативу и продвигает время. После боя стоит заглянуть в «План» и сверить здоровье с ценой лечения. За продвижением первой главы удобно следить в «Сводке». Первая сюжетная встреча после начала вторжения требует снизить мощь Эдды до 11, следующая — до 2 после первой встречи.</p><p><a href="strategic-report.html">Как игра считает мощь →</a> · <a href="walkthrough.html">Дальнейший путь по главам →</a></p>"""
    buildings = """<p>В «Стройке» справа открывается каталог по шесть позиций на страницу. Стрелки под списком перелистывают его. Постройку можно перенести на своё владение с подходящей местностью. Игра проверяет запас золота и запрашивает подтверждение. Новая постройка занимает место прежней и получает свои полные ОЗ.</p>"""
    buildings += illustration("campaign/construction","Первая страница каталога. Для пашни нужны равнины, для лесосеки — лес. Справа у каждой постройки указаны ОЗ и цена.")
    buildings += """<h2>Что окупится в Оулу</h2><p>Пашня стоит 250 золота, даёт 40 золота и 20 еды за ход. Она уже есть в лагере. Лавка приносила бы 150 золота, но для неё нужен город. Дом можно поставить на любой местности. Если заменить им стартовую пашню, армия потеряет 20 еды и 20 золота дохода за ход, зато прибавит 5 к лечению.</p><h2>Цена, прочность и прибавки</h2><p>В таблице денежные и ресурсные прибавки указаны за ход. «Стена» усиливает защиту армии в бою. ОЗ в соседней колонке — прочность самой постройки. У двух зданий в игре расходятся подпись и начисление: академия обещает 30 ресурсов, начисляет 20. Горячий источник обещает 50 лечения, даёт 15 и приносит 150 золота.</p>"""
    buildings += building_table(project)
    report = """<p>В начале первой главы у армии Эдды мощь 16 и 14 земель. У Локи по одному пункту в обеих графах. Сводка считает владения по-разному: обычная земля и город дают по единице мощи, столица даёт три. Поэтому захват столицы сильнее приближает сюжетную развилку, условия которой зависят от мощи врага.</p>"""
    report += illustration("campaign/report","Сводка первого хода. Слева владения и сила Эдды, справа показатели армии Локи и три эффекта конца хода.")
    report += """<h2>Мощь, земли и сила</h2><p>Графа «Земли» считает владения поштучно. «Сила» рядом с землями противника показывает его запас для тактических навыков. «Очки» на панели Локи — счёт кампании. Значение 0 там не мешает атаковать. Критерии отдельных глав приведены в <a href="walkthrough.html">прохождении</a>.</p><h2>Стена и опыт армии</h2><p>На снимке стена равна 10. Это укрепление входит в расчёт урона по обороняющейся стороне. В знаменатель формулы обычного удара прибавляется квадратный корень из укрепления. Опыт армии меняет бонусы боевых тактик. Уровни отдельных бойцов и их опыт можно посмотреть отдельно.</p><h2>В конце хода</h2><p>На снимке «Лечение» равно 50, «Опыт» и «Прирост силы» равны нулю. Лечение восстанавливает ОЗ бойцам, которые пропустили бой. В графу опыта входит прибавка за ход, например +5 от тренировочной площадки. Церковь добавляет 10 к приросту силы. После строительства свежие значения появляются в сводке.</p><p><a href="damage.html">Формула удара с учётом стены</a> · <a href="growth.html">Уровни бойцов</a></p>"""
    items = [("campaign-start","Режимы, сложность и стартовая луна",mode),
             ("first-turn","Первый ход в лагере Оулу",first),("construction","Постройки и доход земель",buildings),
             ("strategic-report","Как читать сводку армии",report)]
    for slug,title,body in items:
        page(slug+".html", title,"mechanics.html",'<div class="wrap guide-layout"><article><div class="crumb"><a href="mechanics.html">Механика Frontier</a></div><h1>'+title+'</h1>'+body+'</article></div>')
        register(title,slug+".html","Механика Frontier")
    return '<ul>'+''.join(f'<li><a href="{slug}.html">{title}</a></li>' for slug,title,_ in items)+'</ul>'
